from __future__ import annotationsfrom pydantic import BaseModel, Fieldclass PredictRequest(BaseModel):    sepal_length: float = Field(..., examples=[5.1])    sepal_width: float = Field(..., examples=[3.5])    petal_length: float = Field(..., examples=[1.4])    petal_width: float = Field(..., examples=[0.2])class PredictResponse(BaseModel):    label: str    label_index: int    confidence: float    probabilities: dict[str, float]